from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class ItemInfo(SchemaObject):
    state = SchemaField(name='state')
    code = SchemaField(name='code', optional=True)

    def __init__(self, state, code):
        self.state = state
        self.code = code

        super(ItemInfo, self).__init__()


class UserNote(SchemaObject):
    state = SchemaField(name='state')

    def __init__(self, state):
        self.state = state

        super(UserNote, self).__init__()


class DetailInfoItem(SchemaObject):
    target_dn = SchemaField(name='target_dn', not_null=True)
    result = SchemaField(name='result', not_null=True)
    angle = SchemaField(name='angle', klass=ItemInfo, optional=True)
    calibration = SchemaField(name='calibration', klass=ItemInfo, optional=True)
    configuration = SchemaField(name='configuration', klass=ItemInfo, optional=True)
    user_note = SchemaField(name='user_note', klass=UserNote, optional=True)

    def __init__(self, target_dn, result, angle, calibration, configuration, user_note):
        self.target_dn = target_dn
        self.result = result
        self.angle = angle
        self.calibration = calibration
        self.configuration = configuration
        self.user_note = user_note

        super(DetailInfoItem, self).__init__()


class DetailedStatus(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    error_text = SchemaField(name='error_text')

    def __init__(self, id, status, error_text):
        self.id = id
        self.status = status
        self.error_text = error_text

        super(DetailedStatus, self).__init__()


class ErrorCode(SchemaObject):
    code = SchemaField(name='code', optional=True)
    description = SchemaField(name='description', optional=True)

    def __init__(self, code, description):
        self.code = code
        self.description = description

        super(ErrorCode, self).__init__()


class RetCommonResult(SchemaObject):
    id = SchemaField(name='id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    detailed_statuses = SchemaField(name='detailed_statuses', many=True, klass=DetailedStatus, optional=True)
    error_message = SchemaField(name='error_message', optional=True)
    error_code = SchemaField(name='error_code', klass=ErrorCode, optional=True)
    detail_info = SchemaField(name='detail_info', optional=True, klass=DetailInfoItem, many=True)

    def __init__(self, id, status, detailed_statuses, error_message, error_code,detail_info):
        self.id = id
        self.status = status
        self.detailed_statuses = detailed_statuses
        self.error_message = error_message
        self.error_code = error_code
        self.detail_info = detail_info

        super(RetCommonResult, self).__init__()
